/*
 * IO_LOGIC_LIBRARY.C
 *
 * FIXED PLATFORM LIBRARY - READ ONLY
 * This file defines the only IO identifiers and instructions available to
 * io_logic_user.c. Do not edit this file in the host editor.
 */

/*
 * 固定库不依赖外部头文件，便于上位机 GCC 检查和 MCU 端移植。
 * uint16_t 的宽度固定为 16 bit。
 */
typedef unsigned short uint16_t;

/*
 * 输入通道定义：固定 8 路，枚举值同时就是输入位图的 bit 位。
 * INPUT_1 到 INPUT_8 对应实际 MCU 引脚如下。
 */
typedef enum
{
    INPUT_1 = 0, /* PE9  */
    INPUT_2 = 1, /* PB7  */
    INPUT_3 = 2, /* PD10 */
    INPUT_4 = 3, /* PA15 */
    INPUT_5 = 4, /* PC0  */
    INPUT_6 = 5, /* PB0  */
    INPUT_7 = 6, /* PB1  */
    INPUT_8 = 7  /* PE8  */
} IO_INPUT_ID;

/*
 * 输出通道定义：固定 8 路。
 * bit0 到 bit3 为继电器，bit4 到 bit7 为晶体管。
 * 逻辑值 1 表示输出打开，逻辑值 0 表示输出关闭。
 */
typedef enum
{
    RELAY_1 = 0,       /* PD15 */
    RELAY_2 = 1,       /* PD14 */
    RELAY_3 = 2,       /* PE0  */
    RELAY_4 = 3,       /* PE1  */
    TRANSISTOR_1 = 4,  /* PA11 */
    TRANSISTOR_2 = 5,  /* PA8  */
    TRANSISTOR_3 = 6,  /* PC7  */
    TRANSISTOR_4 = 7   /* PC6  */
} IO_OUTPUT_ID;

/*
 * 内部指令标识：用于后续 C 逻辑编译器生成字节码和下载协议。
 * 这些编号一旦发布不得改变，否则旧程序的指令含义会发生变化。
 */
typedef enum
{
    OP_INPUT_ACTIVE       = 0x01,
    OP_INPUT_RISING       = 0x02,
    OP_INPUT_FALLING      = 0x03,
    OP_INPUT_MASK         = 0x04,
    OP_OUTPUT_SET         = 0x10,
    OP_OUTPUT_RESET       = 0x11,
    OP_OUTPUT_TOGGLE      = 0x12,
    OP_OUTPUT_PULSE       = 0x13,
    OP_OUTPUT_MASK_READ   = 0x14,
    OP_OUTPUT_MASK_WRITE  = 0x15,
    OP_OUTPUT_ALL_OFF     = 0x16,
    OP_TIMER_PHASE        = 0x20
} IO_OPCODE;

/*
 * IO_INPUT_ACTIVE(INPUT_N)
 * 作用：读取指定输入的当前有效状态。
 * 返回：1 表示输入有效，0 表示输入无效。
 * 参数：只能使用 INPUT_1 到 INPUT_8。
 * 注意：只读操作，不改变任何输出状态。
 */
int IO_INPUT_ACTIVE(IO_INPUT_ID input);

/*
 * IO_INPUT_RISING_EDGE(INPUT_N)
 * 作用：检测输入从无效变为有效的上升沿。
 * 返回：检测到边沿时返回 1，仅在一个扫描周期内有效，否则返回 0。
 * 用途：按钮按下、告警触发、脉冲启动。
 */
int IO_INPUT_RISING_EDGE(IO_INPUT_ID input);

/*
 * IO_INPUT_FALLING_EDGE(INPUT_N)
 * 作用：检测输入从有效变为无效的下降沿。
 * 返回：检测到边沿时返回 1，仅在一个扫描周期内有效，否则返回 0。
 * 用途：按钮释放、告警消失、断线检测。
 */
int IO_INPUT_FALLING_EDGE(IO_INPUT_ID input);

/*
 * IO_INPUT_READ_MASK()
 * 作用：一次读取全部 8 路输入状态。
 * 返回：uint16_t 位图，bit0 对应 INPUT_1，bit7 对应 INPUT_8。
 * 限制：返回值的 bit8 到 bit15 必须为 0。
 */
uint16_t IO_INPUT_READ_MASK(void);

/*
 * IO_OUTPUT_SET(OUTPUT_N)
 * 作用：打开指定的一路继电器或晶体管输出。
 * 参数：只能使用 RELAY_1 到 RELAY_4、TRANSISTOR_1 到 TRANSISTOR_4。
 * 说明：库使用逻辑打开状态，屏蔽继电器底层的高低电平差异。
 */
void IO_OUTPUT_SET(IO_OUTPUT_ID output);

/* IO_OUTPUT_RESET(OUTPUT_N)：关闭指定的一路继电器或晶体管输出。 */
void IO_OUTPUT_RESET(IO_OUTPUT_ID output);

/*
 * IO_OUTPUT_TOGGLE(OUTPUT_N)
 * 作用：翻转指定输出当前的逻辑状态。
 * 注意：不要在无条件代码中连续调用，否则每 10 ms 都会翻转一次。
 */
void IO_OUTPUT_TOGGLE(IO_OUTPUT_ID output);

/*
 * IO_OUTPUT_PULSE(OUTPUT_N, duration_ms)
 * 作用：打开指定输出，持续 duration_ms 毫秒后自动关闭。
 * 参数：duration_ms 范围为 1 到 65535。
 * 说明：非阻塞执行，不会暂停 IO 扫描任务。
 */
void IO_OUTPUT_PULSE(IO_OUTPUT_ID output, uint16_t duration_ms);

/*
 * IO_TIMER_PHASE(interval_ms, phase)
 * 作用：生成一个周期时间条件，phase 从 0 开始。
 * 参数：间隔 10~65535 毫秒；多个相位条件组成一个周期。
 * 说明：条件内部使用 IO_OUTPUT_SET/RESET 等基础输出指令。
 */
int IO_TIMER_PHASE(uint16_t interval_ms, uint16_t phase);

/*
 * IO_OUTPUT_READ_MASK()
 * 作用：读取全部 8 路输出的逻辑状态。
 * 返回：bit0 到 bit3 为继电器，bit4 到 bit7 为晶体管。
 * 注意：返回的是逻辑状态，不等同于外部负载端的实测电压。
 */
uint16_t IO_OUTPUT_READ_MASK(void);

/*
 * IO_OUTPUT_WRITE_MASK(output_mask)
 * 作用：一次写入全部 8 路输出状态。
 * 参数：bit0 到 bit7 有效，高 8 位必须为 0。
 */
void IO_OUTPUT_WRITE_MASK(uint16_t output_mask);

/*
 * IO_OUTPUT_ALL_OFF()
 * 作用：关闭全部 8 路输出。
 * 用途：急停、故障处理、程序初始化和安全复位。
 */
void IO_OUTPUT_ALL_OFF(void);

/*
 * 用户逻辑编写规则：
 * 1. IO_Logic_Run(void) 由平台每 10 ms 自动调用。
 * 2. IO_OUTPUT_PULSE 为非阻塞指令，不要使用延时循环。
 * 3. 输入和输出位图只允许使用 bit0 到 bit7。
 * 4. 禁止定义 main，禁止调用 HAL_*，禁止直接操作 GPIO 和时钟。
 *
 * io_logic_user.c 使用示例：
 *
 * void IO_Logic_Run(void)
 * {
 *     if (IO_INPUT_ACTIVE(INPUT_1))
 *     {
 *         IO_OUTPUT_SET(RELAY_1);
 *     }
 *     else
 *     {
 *         IO_OUTPUT_RESET(RELAY_1);
 *     }
 *
 *     if (IO_INPUT_RISING_EDGE(INPUT_2))
 *     {
 *         IO_OUTPUT_PULSE(TRANSISTOR_1, 1000);
 *     }
 * }
 */
